/* Vora — Fitma website assistant widget.
   Add to any page (ideally site-wide) with ONE line before </body>:
     <script defer src="/vora-widget.js"></script>
   Optional config on that tag:
     data-endpoint="/.netlify/functions/vora"   (default)
     data-image="/vora-wave.png"                (default)
   It injects a floating Vora in the bottom-right and changes nothing else on your page. */
(function () {
  "use strict";
  if (window.__voraLoaded) return;
  window.__voraLoaded = true;

  var me = document.currentScript || (function () {
    var s = document.getElementsByTagName("script");
    return s[s.length - 1];
  })();
  var ENDPOINT = (me && me.getAttribute("data-endpoint")) || "/.netlify/functions/vora";
  var VORA_IMG_EMBED = "data:image/png;base64,";
  var IMG = (me && me.getAttribute("data-image")) || VORA_IMG_EMBED;

  var GREETING = "Hi! I am Vora 👋 Ask me anything! - I will try my best to help you.";
  var SUGGESTED = ["What does Fitma do?", "What is Fitma Tick?", "How do I get started?", "Who do you work with?"];

  var CSS = [
    ".vora-root{--vn:#273545;--vh:#3D5C71;--vs:#6A8599;--vsky:#92AABE;--vline:#e3eaf1;--vbg:#eef4fb;--vbot:#f3f7fb;--vcard:#fff;--vink:#273545;--vinks:#5f7486;}",
    ".vora-root *{box-sizing:border-box;font-family:'Montserrat',-apple-system,BlinkMacSystemFont,'Segoe UI',system-ui,sans-serif}",
    ".vora-launch{position:fixed;right:18px;bottom:18px;z-index:2147483000;display:flex;align-items:center;gap:10px;cursor:pointer;background:none;border:0;padding:0}",
    ".vora-launch .vlbl{background:#fff;border:1px solid var(--vline);border-radius:12px;padding:10px 14px;font-weight:600;font-size:14px;color:var(--vink);box-shadow:0 10px 24px -14px rgba(39,53,69,.6);white-space:nowrap}",
    ".vora-launch img{width:116px;height:auto;filter:drop-shadow(0 14px 18px rgba(39,53,69,.3));transition:transform .15s}",
    ".vora-launch:hover img{transform:translateY(-3px) scale(1.04)}",
    "@media (max-width:520px){.vora-launch .vlbl{display:none}.vora-launch img{width:92px}}",
    ".vora-panel{position:fixed;right:18px;bottom:18px;z-index:2147483001;width:380px;max-width:calc(100vw - 32px);height:560px;max-height:calc(100vh - 36px);background:var(--vcard);border:1px solid var(--vline);border-radius:20px;box-shadow:0 26px 60px -20px rgba(39,53,69,.55);display:flex;flex-direction:column;overflow:hidden;transform:translateY(16px) scale(.98);opacity:0;pointer-events:none;transition:.22s}",
    ".vora-panel.vopen{transform:none;opacity:1;pointer-events:auto}",
    ".vora-head{display:flex;align-items:center;gap:11px;padding:13px 14px;background:var(--vn);color:#fff}",
    ".vora-head .vav{width:50px;height:50px;display:flex;align-items:flex-end;justify-content:center;flex:none}",
    ".vora-head .vav img{width:100%;height:auto}",
    ".vora-head .vwho{flex:1;min-width:0}",
    ".vora-head .vwho b{font-size:16px;display:block;line-height:1.1}",
    ".vora-head .vwho span{font-size:12px;color:#bcd0df;display:flex;align-items:center;gap:5px}",
    ".vora-head .vwho span:before{content:'';width:7px;height:7px;border-radius:50%;background:#17b6a4}",
    ".vora-head button{background:#ffffff1f;border:0;color:#fff;width:30px;height:30px;border-radius:8px;cursor:pointer;font-size:18px;line-height:1}",
    ".vora-head button:hover{background:#ffffff33}",
    ".vora-msgs{flex:1;overflow-y:auto;padding:16px 14px;display:flex;flex-direction:column;gap:10px;background:var(--vbg)}",
    ".vora-m{max-width:84%;padding:10px 13px;border-radius:14px;font-size:14px;white-space:pre-wrap;word-wrap:break-word;line-height:1.45}",
    ".vora-m.vb{background:var(--vbot);color:var(--vink);border:1px solid var(--vline);border-bottom-left-radius:5px;align-self:flex-start}",
    ".vora-m.vu{background:var(--vn);color:#fff;border-bottom-right-radius:5px;align-self:flex-end}",
    ".vora-m.vthink{color:var(--vinks);font-style:italic}",
    ".vora-chips{display:flex;flex-wrap:wrap;gap:7px;padding:0 14px 10px;background:var(--vbg)}",
    ".vora-chip{background:#fff;border:1px solid var(--vline);border-radius:999px;padding:7px 12px;font-size:13px;font-weight:600;color:var(--vh);cursor:pointer}",
    ".vora-chip:hover{border-color:var(--vs)}",
    ".vora-in{display:flex;gap:8px;padding:11px;border-top:1px solid var(--vline);background:#fff}",
    ".vora-in input{flex:1;min-width:0;border:1px solid var(--vline);border-radius:10px;padding:11px 13px;font-size:14px;background:var(--vbg);color:var(--vink)}",
    ".vora-in input:focus{outline:2px solid var(--vsky)}",
    ".vora-in button{flex:none;border:0;background:var(--vn);color:#fff;border-radius:10px;padding:0 16px;font-weight:600;cursor:pointer}",
    ".vora-in button:disabled{opacity:.5;cursor:default}",
    ".vora-foot{font-size:11px;color:var(--vinks);text-align:center;padding:0 10px 8px;background:#fff}"
  ].join("");

  function el(tag, cls, txt) { var e = document.createElement(tag); if (cls) e.className = cls; if (txt != null) e.textContent = txt; return e; }

  function init() {
    var style = el("style"); style.textContent = CSS; document.head.appendChild(style);
    var root = el("div", "vora-root"); document.body.appendChild(root);

    // launcher
    var launch = el("button", "vora-launch"); launch.setAttribute("aria-label", "Open Vora, the Fitma assistant");
    var lbl = el("span", "vlbl", "Hi! Ask me anything 👋");
    var limg = el("img"); limg.src = IMG; limg.alt = "Vora";
    launch.appendChild(lbl); launch.appendChild(limg); root.appendChild(launch);

    // panel
    var panel = el("div", "vora-panel"); panel.setAttribute("role", "dialog"); panel.setAttribute("aria-label", "Vora, the Fitma assistant");
    var head = el("div", "vora-head");
    var av = el("span", "vav"); var aimg = el("img"); aimg.src = IMG; aimg.alt = "Vora"; av.appendChild(aimg);
    var who = el("div", "vwho"); who.appendChild(el("b", null, "Vora")); who.appendChild(el("span", null, "Fitma Assistant"));
    var closeBtn = el("button", null, "×"); closeBtn.setAttribute("aria-label", "Close");
    head.appendChild(av); head.appendChild(who); head.appendChild(closeBtn);
    var msgs = el("div", "vora-msgs");
    var chips = el("div", "vora-chips");
    var inrow = el("div", "vora-in");
    var input = el("input"); input.type = "text"; input.placeholder = "Ask about Fitma or Fitma Tick…"; input.autocomplete = "off";
    var send = el("button", null, "Send");
    inrow.appendChild(input); inrow.appendChild(send);
    var foot = el("div", "vora-foot", "Vora is an AI assistant and can make mistakes.");
    panel.appendChild(head); panel.appendChild(msgs); panel.appendChild(chips); panel.appendChild(inrow); panel.appendChild(foot);
    root.appendChild(panel);

    var history = [], busy = false;

    function addMsg(role, text) {
      var d = el("div", "vora-m " + (role === "user" ? "vu" : "vb"), text);
      msgs.appendChild(d); msgs.scrollTop = msgs.scrollHeight; return d;
    }
    function renderChips() {
      chips.innerHTML = ""; if (history.length) return;
      SUGGESTED.forEach(function (q) {
        var c = el("button", "vora-chip", q);
        c.addEventListener("click", function () { input.value = q; submit(); });
        chips.appendChild(c);
      });
    }
    function open() {
      panel.classList.add("vopen"); launch.style.display = "none";
      if (!msgs.childElementCount) { addMsg("bot", GREETING); renderChips(); }
      setTimeout(function () { input.focus(); }, 250);
    }
    function close() { panel.classList.remove("vopen"); launch.style.display = "flex"; }
    launch.addEventListener("click", open);
    closeBtn.addEventListener("click", close);

    function submit() {
      var text = input.value.trim(); if (!text || busy) return;
      input.value = ""; addMsg("user", text); history.push({ role: "user", content: text });
      chips.innerHTML = ""; busy = true; send.disabled = true;
      var bubble = addMsg("bot", "Thinking…"); bubble.classList.add("vthink");
      fetch(ENDPOINT, {
        method: "POST", headers: { "content-type": "application/json" },
        body: JSON.stringify({ messages: history })
      }).then(function (r) { return r.json().then(function (d) { return { ok: r.ok, d: d }; }); })
        .then(function (res) {
          bubble.classList.remove("vthink");
          if (res.ok && res.d && res.d.text) {
            bubble.textContent = res.d.text; history.push({ role: "assistant", content: res.d.text });
          } else {
            bubble.textContent = (res.d && res.d.error) ? res.d.error : "Sorry, I hit a snag. Please try again, or reach us on WhatsApp +94 76 650 1832.";
            history.pop();
          }
        }).catch(function () {
          bubble.classList.remove("vthink");
          bubble.textContent = "Sorry, I couldn't connect. Please try again, or reach us on WhatsApp +94 76 650 1832.";
          history.pop();
        }).then(function () {
          busy = false; send.disabled = false; msgs.scrollTop = msgs.scrollHeight; input.focus();
        });
    }
    send.addEventListener("click", submit);
    input.addEventListener("keydown", function (e) { if (e.key === "Enter") submit(); });
  }

  if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", init);
  else init();
})();
